// The stack sizes configured in the interface for two Sporadic interfaces
#define SPORADIC_IF_1_STACK_SIZE 8000
#define SPORADIC_IF_2_STACK_SIZE 5000

// Buffers for holding the stack sizes read at run time by thread_stack_size_visitor
static int iStackSize_SpIf1 = 0;
static int iStackSize_SpIf2 = 0;


// Callback passed into rtems_task_iterate
static bool thread_stack_size_visitor(Thread_Control *the_thread, void *arg)
{
    const uint32_t iThisThreadId = the_thread->Object.id;
    const Stack_Control *stack = &the_thread->Start.Initial_stack;

    if (threads_info[test_sporadic_sporadic_if_1].id == iThisThreadId)
    {
        iStackSize_SpIf1 = stack->size;
	}
    else if (threads_info[test_sporadic_sporadic_if_2].id == iThisThreadId)
    {
        iStackSize_SpIf2 = stack->size;
	}

    return false;
}


// Constructor
void test_sporadic_startup(void)
{
    // Register the test that this TASTE Function will submit a result for
    testresult_register_test(TF_TEST_ID__TestStacks);
}


// Determine pass/fail and submit result over UART
void test_sporadic_PI_trigger_check(void)
{
    char aMsgBuff[100];

    // Get the rtems OS to run our stack-size-visitor funtion to grab stack sizes for key IFs
    rtems_task_iterate(thread_stack_size_visitor, NULL);

    /* Determine the test result ------- */

    // SP IF 1 stack size not as expected?
    if (iStackSize_SpIf1 != SPORADIC_IF_1_STACK_SIZE)
    {
        sprintf(aMsgBuff, "Stack size of sporadic_if_1 not %i as expected but rather %i", SPORADIC_IF_1_STACK_SIZE, iStackSize_SpIf1);
        testresult_report_fail(TF_TEST_ID__TestStacks, aMsgBuff);
    }

    // SP IF 2 stack size not as expected?
    else if (iStackSize_SpIf2 != SPORADIC_IF_2_STACK_SIZE)
    {
        sprintf(aMsgBuff, "Stack size of sporadic_if_2 not %i as expected but rather %i", SPORADIC_IF_2_STACK_SIZE, iStackSize_SpIf2);
        testresult_report_fail(TF_TEST_ID__TestStacks, aMsgBuff);
    }

    // Else its a pass
    else
    {
        testresult_report_pass(TF_TEST_ID__TestStacks);
    }
}


